/* ========================================================================== */
/* BFUSION Financial KPI Narrative                                            */
/* Header / toolbar ported from bfusion-FinancialSCurve, prefix fsc- → fkn-. */
/* ========================================================================== */
/***********************************************************
 * 1. Base Structure
 ***********************************************************/
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  color: #242424;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.fkn-root {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
.bfusion-landing-wrap {
  width: 100%;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
/* Header bar (title + subtitle + info button) */
.fkn-header {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 16px 6px 16px;
  border-bottom: 1px solid #E5E7EB;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8F9FB 100%);
  position: relative;
}
.fkn-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.fkn-header__title {
  font-weight: 700;
  color: #242424;
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fkn-header__subtitle {
  margin-top: 2px;
  color: #6C757D;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fkn-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E3E6EC;
  background: #fff;
  color: #6B7280;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  padding: 0;
  transition: all 0.15s ease;
}
.fkn-header__info:hover,
.fkn-header__info:focus-visible {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.fkn-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.fkn-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 300px;
  max-width: calc(100% - 24px);
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: #242424;
  line-height: 1.45;
}
.fkn-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.fkn-header__info-pop ul li {
  margin: 3px 0;
  color: #6C757D;
}
.fkn-info-pop__title {
  font-weight: 700;
  color: #242424;
  margin-bottom: 4px;
}
.fkn-info-pop__desc {
  color: #6C757D;
}
/* Toolbar (on-canvas Status Date picker) */
.fkn-toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 16px;
  background: #F8F9FB;
  border-bottom: 1px solid #E5E7EB;
  font-size: 11px;
  color: #6C757D;
}
.fkn-toolbar__label {
  flex: 0 0 auto;
  font-size: 9.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #6C757D;
  white-space: nowrap;
  cursor: pointer;
}
.fkn-toolbar__date {
  flex: 0 0 auto;
  font: inherit;
  font-size: 11px;
  color: #242424;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 10px;
  padding: 1px 8px;
  accent-color: #E8612A;
}
.fkn-toolbar__date:focus {
  outline: none;
  border-color: #E8612A;
}
.fkn-toolbar__hint {
  min-width: 0;
  font-size: 10px;
  color: #6C757D;
  font-style: italic;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.fkn-toolbar__hint--warn {
  color: #B45309;
  font-style: normal;
  font-weight: 600;
}
/***********************************************************
 * 2. Landing Page
 ***********************************************************/
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
}
.bfusion-landing__metadata a {
  color: #8C8C8C;
  text-decoration: none;
}
.bfusion-landing__metadata a:hover {
  text-decoration: underline;
}
/* Card grid */
.bfusion-card-wrap {
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 10px;
  background: #f4f5f7;
}
.bfusion-card-wrap::-webkit-scrollbar {
  width: 6px;
}
.bfusion-card-wrap::-webkit-scrollbar-thumb {
  background: #c8c8c8;
  border-radius: 3px;
}
.bfusion-card-wrap::-webkit-scrollbar-thumb:hover {
  background: #aaa;
}
.bfusion-card-wrap::-webkit-scrollbar-track {
  background: transparent;
}
.bfusion-kpi-card {
  transition: box-shadow 0.2s ease, transform 0.15s ease;
}
.bfusion-kpi-card:hover {
  box-shadow: 0 3px 12px rgba(0, 0, 0, 0.1) !important;
  transform: translateY(-1px);
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* The badge sits in the 24px clear-zone under the cards. Discreet but
   readable: no fill, no border, dark grey text. Scoped under the root so it
   outranks the badge CSS that license.ts injects at runtime. */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
  line-height: 1;
}
.bfusion-root .bfusion-license-badge {
  position: static;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  color: #4B5563;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-root .bfusion-license-badge em {
  color: #E8612A;
  font-style: normal;
  font-weight: 600;
  opacity: 1;
}
.bfusion-license-badge__icon {
  font-size: 10px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
